        : null;
    case "min":
    case "max":
      return kind === "number" &&
        typeof argument === "number" &&
        Number.isFinite(argument)
        ? { operator, argument, message }
        : null;
    case "minDate":
    case "maxDate":
      return kind === "date" && isCalendarDate(argument)
        ? { operator, argument, message }
        : null;
    case "pattern":
      return kind === "text" &&
        typeof argument === "string" &&
        compilePattern(argument)
        ? { operator, argument, message }
        : null;
    default:
      return null;
  }
}

function validRanges(rules: readonly Rule[]): boolean {
  const lowerBounds = {
    min: "max",
    minDate: "maxDate",
    minLength: "maxLength",
  } as const;
  return rules.every((rule) => {
    if (
      rule.operator !== "min" &&
      rule.operator !== "minDate" &&
      rule.operator !== "minLength"
