      return true;
    const upper = lowerBounds[rule.operator];
    return !rules.some(
      (other) =>
        other.operator === upper &&
        "argument" in other &&
        rule.argument > other.argument,
    );
  });
}

function decodeOptions(input: unknown, required: boolean): Option[] | null {
