    !Array.isArray(input) ||
    input.length > MAX_OPTIONS ||
    (required && !input.length)
  )
    return null;
  const options: Option[] = [];
  const ids = new Set<string>();
  for (const option of input) {
    if (
      !isRecord(option) ||
      !isSafeId(option["id"]) ||
      ids.has(option["id"]) ||
      !copy(option["label"])
