    !isSafeId(id) ||
    !copy(label) ||
    !copy(helpText, true) ||
    !copy(errorMessage) ||
    typeof required !== "boolean" ||
    !boundedInteger(order) ||
    !isFieldKind(kind) ||
    !Array.isArray(rules) ||
    rules.length > MAX_RULES
  )
    return null;
