  if (
    parsedPurpose === "vehicleYear" &&
    (!required || !parsedRules.some((r) => r.operator === "vehicleYearRange"))
  )
    return null;
  const field = fieldShape(
    {
      id,
      label,
      helpText,
      errorMessage,
      required,
      order,
      purpose: parsedPurpose,
      rules: parsedRules,
    },
    kind,
    options,
    defaultValue,
  );
