    const compatibleKind =
      kind === field.kind ||
      (kind === "text" && field.kind === "date") ||
      (kind === "date" && field.kind === "text");
    entries.push([
      field.id,
      {
        kind: field.kind,
        value: compatibleKind && represents(field, value) ? value : null,
      },
    ]);
  }
