import { compilePattern, matchesPattern } from "./pattern.ts";
export { matchesPattern };

export type Country = "co" | "cl";
export type FieldValue = string | number | boolean;
export type FieldKind = "text" | "number" | "select" | "date" | "checkbox";
type FieldPurpose =
  | "dateOfBirth"
  | "vehicleYear"
  | "identityDocument"
  | "licensePlate";

type Rule =
  | { operator: "required" | "email" | "vehicleYearRange"; message: string }
  | {
      operator: "minLength" | "maxLength" | "min" | "max" | "minimumAge";
      argument: number;
      message: string;
    }
  | {
      operator: "pattern" | "minDate" | "maxDate";
      argument: string;
      message: string;
    };

type FieldCommon = {
  id: string;
  label: string;
  helpText: string;
  errorMessage: string;
  required: boolean;
  order: number;
  rules: readonly Rule[];
  purpose?: FieldPurpose;
};
type Option = { id: string; label: string };
export type FieldDefinition = FieldCommon &
  (
    | { kind: "text" | "date"; defaultValue?: string }
    | { kind: "number"; defaultValue?: number }
    | { kind: "checkbox"; defaultValue?: boolean }
    | { kind: "select"; defaultValue?: string; options: readonly Option[] }
  );

export type FormDefinition = {
  schemaVersion: 1;
  country: Country;
  fields: readonly FieldDefinition[];
};
export type DraftEntry = { kind: FieldKind; value: FieldValue | null };
export type QuoteDraft = Readonly<Record<string, DraftEntry>>;

const kinds: readonly FieldKind[] = [
  "text",
  "number",
  "select",
  "date",
  "checkbox",
];
const purposeKinds: Record<FieldPurpose, FieldKind> = {
  dateOfBirth: "date",
  vehicleYear: "number",
  identityDocument: "text",
  licensePlate: "text",
};
const MAX_FIELDS = 40;
const MAX_OPTIONS = 60;
const MAX_RULES = 12;
const MAX_TEXT = 240;
const MAX_INPUT = 256;

export function isCountry(value: unknown): value is Country {
  return value === "co" || value === "cl";
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

export function isSafeId(value: unknown): value is string {
  return (
    typeof value === "string" &&
    /^[a-z][a-z0-9-]{0,39}$/.test(value) &&
    value !== "constructor"
  );
}

export function isFieldKind(value: unknown): value is FieldKind {
  return kinds.some((kind) => kind === value);
}

function copy(value: unknown, allowEmpty = false): value is string {
  return (
    typeof value === "string" &&
    value.length <= MAX_TEXT &&
    (allowEmpty || !!value.trim())
  );
}

function boundedInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function isCalendarDate(value: unknown): value is string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value))
    return false;
  const [year, month, day] = value.split("-").map(Number);
  if (year < 1 || month < 1 || month > 12 || day < 1) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  return (
    day <=
    [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
  );
}

import { decodeForm, isRecord, type Country } from "@quote/contract";

export const FORM_UID = "api::quote-content.form-configuration";

// Keep scalars inside an object in Strapi JSON fields so SQLite preserves
// Boolean and string types through storage and editorial round trips.
function scalar(raw: unknown): unknown {
  if (raw === null || raw === undefined) return undefined;
  return isRecord(raw) && Object.keys(raw).length === 1 && raw["value"] != null
    ? raw["value"]
    : raw;
}

function projectField(raw: unknown): unknown {
  if (!isRecord(raw)) return null;
  const {
    fieldKey,
    label,
    helpText,
    errorMessage,
    kind,
    required,
    order,
    purpose,
    defaultValue,
    rules,
    options,
  } = raw;
  return {
    id: fieldKey,
    label,
    helpText: helpText === null ? "" : helpText,
    errorMessage,
    kind,
    required,
    order,
    purpose: purpose ?? undefined,
    defaultValue: scalar(defaultValue),
    rules: Array.isArray(rules)
      ? rules.map((rule: unknown) =>
          isRecord(rule)
            ? {
                operator: rule["operator"],
                argument: scalar(rule["argument"]),
                message: rule["message"],
              }
            : null,
        )
      : rules,
    options:
      Array.isArray(options) && (kind === "select" || options.length)
        ? options.map((option: unknown) =>
            isRecord(option)
              ? { id: option["optionKey"], label: option["label"] }
              : null,
          )
        : undefined,
  };
}

export function projectForm(document: unknown, country: Country) {
  if (!isRecord(document) || !Array.isArray(document["fields"])) return null;
  return decodeForm(
    {
      schemaVersion: 1,
      country: document["country"],
      fields: document["fields"].map(projectField),
    },
    country,
    null,
  );
}
